import 'package:flutter/material.dart'; import '../services/poll_service.dart'; import '../widgets/page_frame.dart'; import 'poll_voting_screen.dart';
class ParticipateScreen extends StatefulWidget { const ParticipateScreen({super.key, required this.service}); final PollService service; @override State<ParticipateScreen> createState() => _ParticipateState(); }
class _ParticipateState extends State<ParticipateScreen> { final code = TextEditingController(); String? error; Future<void> join() async { final poll = await widget.service.find(code.text); if (!mounted) return; if (poll == null) { setState(() => error = 'No poll found with that room code.'); return; } Navigator.push(context, MaterialPageRoute(builder: (_) => PollVotingScreen(service: widget.service, poll: poll))); }
 @override Widget build(BuildContext context) => PageFrame(title: 'Participate', onBack: () => Navigator.pop(context), child: Padding(padding: const EdgeInsets.all(24), child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [const Icon(Icons.meeting_room_outlined, size: 64), const SizedBox(height: 16), const Text('Join a poll', style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold)), const SizedBox(height: 20), TextField(controller: code, keyboardType: TextInputType.number, decoration: InputDecoration(labelText: 'Room code', errorText: error)), const SizedBox(height: 16), SizedBox(width: double.infinity, child: FilledButton(onPressed: join, child: const Text('Join Poll')))]))); }
